def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = 0
    for a in op:
        if a == 'C':
            op_c += 1

    # Mostly cooperative opponent
    if op_c >= n - max(1, n // 10):
        if op[-1] == 'D':
            return 'D'
        if n >= 98:
            return 'D'
        if n >= 90:
            return 'D' if rng.random() < 0.35 else 'C'
        return 'C'

    # Mostly defective opponent
    if op_c <= n // 3:
        if me[-1] == 'D' and op[-1] == 'D':
            return 'D'
        if op[-1] == 'D':
            return 'D'
        return 'C'

    # Mid game: TFT with limited forgiveness and endgame pressure
    last_me = me[-1]
    last_op = op[-1]

    if last_op == 'D':
        if last_me == 'D':
            if op_c > n * 0.7 and rng.random() < 0.4:
                return 'C'
            return 'D'
        if op_c > n * 0.7 and rng.random() < 0.2:
            return 'C'
        return 'D'

    if n > 85:
        return 'D' if rng.random() < 0.35 else 'C'
    return 'C'
